"""Phone protocol isolation/replay tests; generated bytes are not speech evidence."""
import base64
import copy
import hashlib
import importlib.util
import json
from pathlib import Path
import tempfile
import threading
import unittest
import urllib.error
import urllib.request
import uuid

from heartball_store import Store, Conflict
from heartball_mobile import MobileIngest
from heartball_processing import Processor
from test_heartball_processing import FakeASR, FakeModel


def uid(): return str(uuid.uuid4())


class MobileTests(unittest.TestCase):
    def setUp(self):
        self.temp = tempfile.TemporaryDirectory()
        self.store = Store(Path(self.temp.name))
        self.asr, self.model = FakeASR(), FakeModel()
        self.processor = Processor(self.store, self.model, self.asr)
        self.ingest = MobileIngest(self.store, self.processor.agent)
        self.manifest = {'id': uid(), 'device_id': uid(), 'started_at': '2026-10-20T23:59:00+08:00',
            'card_file': 'note20261020-235900.opus', 'batch_seconds': 60,
            'processing': {'asr': True, 'agent': True, 'source_kind': 'unknown'}}
        self.stream = uid()

    def tearDown(self):
        self.processor.close(); self.store.db.close(); self.temp.cleanup()

    def batch(self, sequence=0, start=0, raw=b'a' * 120000, stream=None, at='2026-10-20T23:59:00+08:00'):
        return {'id': uid(), 'kind': 'batch', 'session': self.manifest, 'stream_id': stream or self.stream,
            'sequence': sequence, 'start_byte': start, 'end_byte': start + len(raw),
            'stream_started_at': at, 'received_at': '2026-10-21T00:10:00+08:00',
            'reason': 'duration', 'sha256': hashlib.sha256(raw).hexdigest(), 'audio_base64': base64.b64encode(raw).decode()}

    def tick(self):
        for _ in range(40):
            if not self.processor.tick(): break

    def test_retry_after_lost_response_and_restart_is_idempotent(self):
        batch = self.batch()
        self.ingest.accept(batch)
        self.tick()
        # The server accepted audio, but the phone never received its response.
        self.ingest = MobileIngest(self.store, self.processor.agent)
        self.assertTrue(self.ingest.accept(batch)['duplicate'])
        self.tick()
        self.assertEqual(self.asr.calls, 1)
        self.assertEqual(self.store.db.execute('SELECT COUNT(*) FROM batches').fetchone()[0], 1)
        changed = copy.deepcopy(batch); changed['reason'] = 'changed'
        with self.assertRaises(Conflict): self.ingest.accept(changed)

    def test_bad_hash_out_of_order_and_gap_cannot_be_hidden(self):
        bad = self.batch(); bad['sha256'] = '0' * 64
        with self.assertRaises(ValueError): self.ingest.accept(bad)
        self.assertEqual(self.store.db.execute('SELECT COUNT(*) FROM sessions').fetchone()[0], 0)
        with self.assertRaises(Conflict): self.ingest.accept(self.batch(sequence=1))
        self.ingest.accept(self.batch())
        with self.assertRaises(Conflict): self.ingest.accept(self.batch(sequence=1, start=120040))
        self.ingest.accept({'id': uid(), 'session': self.manifest, 'kind': 'gap', 'at': '2026-10-21T00:00:00+08:00', 'reason': 'bluetooth'})
        self.ingest.accept(self.batch(sequence=1, raw=b'b' * 4000, stream=uid(), at='2026-10-21T00:09:58+08:00'))
        self.assertEqual(self.store.state()['session']['gapCount'], 1)

    def test_recording_time_uses_each_phone_stream_not_upload_clock(self):
        self.ingest.accept(self.batch())
        self.ingest.accept(self.batch(sequence=1, start=120000, raw=b'b' * 2000))
        self.ingest.accept(self.batch(sequence=2, stream=uid(), raw=b'c' * 2000, at='2026-10-21T00:09:58+08:00'))
        self.tick()
        times = {r[0] for r in self.store.db.execute('SELECT occurred_at FROM documents')}
        self.assertIn('2026-10-20T23:59:00+08:00', times)
        self.assertIn('2026-10-21T00:00:00+08:00', times)
        self.assertIn('2026-10-21T00:09:58+08:00', times)
        self.assertEqual(self.processor.agent.state()['confirmedMemoryCount'], 0)

    def test_focus_tail_and_finish_share_audio_and_preserve_pending_card_proof(self):
        self.ingest.accept(self.batch(raw=b'a' * 40000))
        self.ingest.accept(self.batch(sequence=1, start=40000, raw=b'b' * 2000))
        self.ingest.accept({'id': uid(), 'session': self.manifest, 'kind': 'focus', 'focus_id': uid(),
            'started_at': self.manifest['started_at'], 'ended_at': '2026-10-21T00:00:00+08:00',
            'ranges': [{'stream_id': self.stream, 'start_byte': 40000, 'end_byte': 42000}]})
        self.ingest.accept({'id': uid(), 'session': self.manifest, 'kind': 'finish', 'at': '2026-10-21T00:00:00+08:00'})
        self.tick()
        self.assertEqual(self.asr.calls, 2)
        self.assertEqual(len(self.processor.agent.state()['documents']), 3)
        self.assertEqual(self.store.state()['session']['archiveStatus'], 'phone_saved_card_verification_pending')
        with self.assertRaises(Conflict): self.ingest.accept(self.batch(sequence=2, start=42000))

    def test_session_policy_and_device_identity_are_immutable(self):
        batch = self.batch(); self.ingest.accept(batch)
        other = self.batch(sequence=1, start=120000)
        other['session'] = copy.deepcopy(self.manifest)
        other['session']['processing']['source_kind'] = 'live_conversation'
        with self.assertRaises(Conflict): self.ingest.accept(other)

    def test_local_asr_busy_waits_without_consuming_retries(self):
        import httpx
        from openai import RateLimitError
        self.ingest.accept(self.batch())
        original = self.asr.transcribe
        def busy(*args):
            raise RateLimitError('busy', response=httpx.Response(429, request=httpx.Request('POST', 'http://127.0.0.1/test')),
                                 body={'code': 'concurrency_exceeded'})
        self.asr.transcribe = busy
        self.processor.tick()
        row = self.store.db.execute("SELECT status,error,attempts FROM jobs WHERE kind='asr_audio'").fetchone()
        self.assertEqual(tuple(row), ('retryable', 'provider_busy', 0))
        self.asr.transcribe = original
        self.store.db.execute('UPDATE jobs SET available_at=0'); self.store.db.commit()
        self.tick()
        self.assertEqual(self.asr.calls, 1)

    def test_reference_requires_unique_alignment_size_hash_and_saved_end(self):
        live = bytes(range(40)) * 50
        tail = b'z' * 80
        self.ingest.accept(self.batch(raw=live))
        self.ingest.accept({'id': uid(), 'session': self.manifest, 'kind': 'finish', 'at': '2026-10-21T00:00:00+08:00'})
        card = live + tail
        chunk = {'id': uid(), 'session': self.manifest, 'kind': 'reference_chunk', 'offset': 0,
                 'sha256': hashlib.sha256(card).hexdigest(), 'audio_base64': base64.b64encode(card).decode()}
        self.ingest.accept(chunk)
        final = {'id': uid(), 'session': self.manifest, 'kind': 'reference_complete', 'card_file': self.manifest['card_file'],
                 'expected_bytes': len(card), 'end_code': 1, 'sha256': hashlib.sha256(card).hexdigest()}
        with self.assertRaises(ValueError): self.ingest.accept(final)
        final['end_code'] = 0
        self.ingest.accept(final)
        proof = json.loads(self.store.session(self.manifest['id'])['archive'])
        self.assertEqual(proof['missingLiveRanges'], [[2000, 2080]])
        self.assertEqual(proof['status'], 'phone_card_bytes_verified')
        self.assertTrue(self.ingest.accept(final)['duplicate'])

    def test_ambiguous_reference_never_claims_repair(self):
        live = b'a' * 2000
        self.ingest.accept(self.batch(raw=live))
        self.ingest.accept({'id': uid(), 'session': self.manifest, 'kind': 'finish', 'at': '2026-10-21T00:00:00+08:00'})
        card = live * 2
        self.ingest.accept({'id': uid(), 'session': self.manifest, 'kind': 'reference_chunk', 'offset': 0,
                 'sha256': hashlib.sha256(card).hexdigest(), 'audio_base64': base64.b64encode(card).decode()})
        with self.assertRaises(Conflict):
            self.ingest.accept({'id': uid(), 'session': self.manifest, 'kind': 'reference_complete', 'card_file': self.manifest['card_file'],
                 'expected_bytes': len(card), 'end_code': 0, 'sha256': hashlib.sha256(card).hexdigest()})
        self.assertEqual(self.store.state()['session']['archiveStatus'], 'phone_saved_card_verification_pending')

    def test_verified_long_gap_reuses_pipeline_without_retranscribing_live_audio(self):
        first, missed, last = b'a' * 2000, b'c' * 12000, b'b' * 2000
        self.ingest.accept(self.batch(raw=first))
        self.ingest.accept(self.batch(sequence=1, stream=uid(), raw=last, at='2026-10-21T00:00:00+08:00'))
        self.ingest.accept({'id': uid(), 'session': self.manifest, 'kind': 'finish', 'at': '2026-10-21T00:01:00+08:00'})
        self.tick(); before = self.asr.calls
        card = first + missed + last
        self.ingest.accept({'id': uid(), 'session': self.manifest, 'kind': 'reference_chunk', 'offset': 0,
            'sha256': hashlib.sha256(card).hexdigest(), 'audio_base64': base64.b64encode(card).decode()})
        complete = {'id': uid(), 'session': self.manifest, 'kind': 'reference_complete', 'card_file': self.manifest['card_file'],
            'expected_bytes': len(card), 'end_code': 0, 'sha256': hashlib.sha256(card).hexdigest()}
        self.ingest.accept(complete); self.tick()
        self.assertEqual(self.asr.calls, before + 1)
        repair = self.store.db.execute("SELECT * FROM batches WHERE reason='card_gap_repair'").fetchone()
        self.assertEqual(Path(repair['filename']).read_bytes(), missed)
        self.assertEqual(repair['end_byte'] - repair['start_byte'], 12000)
        # A second receipt identity for the same completed reference cannot create
        # a second repair stream, job, or ASR request.
        complete['id'] = uid(); self.ingest.accept(complete); self.tick()
        self.assertEqual(self.asr.calls, before + 1)
        self.assertEqual(self.store.db.execute("SELECT COUNT(*) FROM batches WHERE reason='card_gap_repair'").fetchone()[0], 1)

    def recovery_manifest(self):
        from heartball_card_segments import segment_id,continuation_clock
        self.ingest.accept({'id':uid(),'session':self.manifest,'kind':'finish','at':'2026-10-21T05:00:00+08:00'})
        proof={'status':'phone_card_bytes_verified','sha256':'a'*64,'bytes':21602000}
        self.store.update_session(self.manifest['id'],archive=json.dumps(proof))
        raw=b'c'*12000;name='note20261021-025901.opus'
        child=copy.deepcopy(self.manifest);child['id']=segment_id(self.manifest['id'],name);child['card_file']=name
        child['started_at']=continuation_clock(self.manifest,'2026-10-21T05:00:00+08:00',self.manifest['card_file'],21602000,name,len(raw))
        child['recovery']={'root_id':self.manifest['id'],'previous_file':self.manifest['card_file'],'previous_sha256':'a'*64,'expected_bytes':len(raw),'sha256':hashlib.sha256(raw).hexdigest()}
        return child,raw

    def test_saved_following_segment_has_own_recording_clock_and_replay_does_not_repeat_asr(self):
        child,raw=self.recovery_manifest()
        finish={'id':uid(),'session':child,'kind':'finish','at':'2026-10-21T02:59:07+08:00'}
        self.ingest.accept(finish)
        chunk={'id':uid(),'session':child,'kind':'reference_chunk','offset':0,'audio_base64':base64.b64encode(raw).decode(),'sha256':hashlib.sha256(raw).hexdigest()}
        self.ingest.accept(chunk)
        complete={'id':uid(),'session':child,'kind':'reference_complete','card_file':child['card_file'],'expected_bytes':len(raw),'end_code':0,'sha256':hashlib.sha256(raw).hexdigest()}
        self.ingest.accept(complete);self.tick();before=self.asr.calls
        self.assertEqual(before,1)
        doc=self.store.db.execute('select occurred_at from documents where session_id=?',(child['id'],)).fetchone()
        self.assertEqual(doc[0],child['started_at'])
        self.ingest=MobileIngest(self.store,self.processor.agent)
        finish['id']=uid();self.ingest.accept(finish)
        self.assertEqual(json.loads(self.store.session(child['id'])['archive'])['status'],'phone_card_bytes_verified')
        complete['id']=uid();self.ingest.accept(complete);self.tick()
        self.assertEqual(self.asr.calls,before)
        self.assertEqual(self.store.db.execute('select count(*) from mobile_card_segments').fetchone()[0],1)

    def test_following_segment_rejects_wrong_hash_clock_policy_or_identity(self):
        child,raw=self.recovery_manifest()
        for field,value in [('previous_sha256','b'*64),('previous_file','note20261021-000000.opus')]:
            bad=copy.deepcopy(child);bad['recovery'][field]=value
            with self.assertRaises(Conflict):self.ingest.accept({'id':uid(),'session':bad,'kind':'finish','at':'2026-10-21T02:59:07+08:00'})
        bad=copy.deepcopy(child);bad['started_at']='2026-10-22T12:00:00+08:00'
        with self.assertRaises(Conflict):self.ingest.accept({'id':uid(),'session':bad,'kind':'finish','at':'2026-10-21T02:59:07+08:00'})
        self.assertEqual(self.store.db.execute('select count(*) from mobile_card_segments').fetchone()[0],0)

    def test_long_clock_hole_and_short_previous_file_never_establish_segment_lineage(self):
        from heartball_card_segments import continuation_clock
        with self.assertRaises(Conflict):continuation_clock(self.manifest,'2026-10-21T19:53:01+08:00',self.manifest['card_file'],21602000,'note20261021-050000.opus',12000)
        with self.assertRaises(Conflict):continuation_clock(self.manifest,'2026-10-21T19:53:01+08:00',self.manifest['card_file'],2000,'note20261020-235901.opus',12000)

    def test_http_auth_size_and_no_hardware_control(self):
        spec = importlib.util.spec_from_file_location('phone_http', Path(__file__).with_name('heartball-mobile-service.py'))
        module = importlib.util.module_from_spec(spec); spec.loader.exec_module(module)
        from types import SimpleNamespace
        server = module.http.Server(('127.0.0.1', 0), module.Handler)
        server.token = 'test'; server.processor = self.processor
        server.engine = SimpleNamespace(store=self.store, max_seconds=86400)
        server.mobile = self.ingest
        thread = threading.Thread(target=server.serve_forever, daemon=True); thread.start()
        def post(path, body, token='test'):
            request = urllib.request.Request(f'http://127.0.0.1:{server.server_port}' + path,
                data=json.dumps(body).encode(), headers={'Authorization': 'Bearer ' + token, 'Content-Type': 'application/json'})
            return json.loads(urllib.request.urlopen(request).read())
        try:
            with self.assertRaises(urllib.error.HTTPError) as error: post('/v1/mobile/ingest', self.batch(), 'wrong')
            self.assertEqual(error.exception.code, 401)
            with self.assertRaises(urllib.error.HTTPError) as error: post('/v1/capture/start', {})
            self.assertEqual(error.exception.code, 405)
            self.assertTrue(post('/v1/mobile/ingest', self.batch())['accepted'])
        finally:
            server.shutdown(); server.server_close(); thread.join()


if __name__ == '__main__': unittest.main()
